	public void ChangeJoeyImage()
	{
		StartCoroutine(ChangeJoeyImageCoroutine());
	}

	IEnumerator ChangeJoeyImageCoroutine()
	{
		if (PData.Instance.playerHealth < PData.Instance.lastPlayerHealth)
		{
			m_View.JoeyImage.sprite = sadSprite;
		}
		else if (PData.Instance.playerHealth > PData.Instance.lastPlayerHealth)
		{
			m_View.JoeyImage.sprite = happySprite;
		}
		else if (PData.Instance.playerHealth <= 0)
		{
			m_View.JoeyImage.sprite = deathSprite;
		}
		yield return new WaitForSeconds(0.5f);
		m_View.JoeyImage.sprite = sleepSprite;
	}

	private UICardSimpleControl GetCardSimple(Transform parent)
	{
		for (int i = 0; i < m_CardSimplePool.Count; i++)
		{
			if (!m_CardSimplePool[i].gameObject.activeSelf)
			{
				m_CardSimplePool[i].gameObject.SetActive(true);
				m_CardSimplePool[i].transform.SetParent(parent);
				return m_CardSimplePool[i];
			}
		}

		UICardSimpleControl cardControl = this.Asset.OpenUI<UICardSimpleControl>(parent);
		m_CardSimplePool.Add(cardControl);
		return cardControl;
	}

	private Card CreateCard(string cardId)
	{
		Card card = GData.Instance.GetCardConfigById(cardId).Clone();
		UniqueIdGen++;
		card.UniqueId = UniqueIdGen;
		m_CardDict[UniqueIdGen] = card;
		return card;
	}

	public void AddCardList(ECardType cardType, List<string> cardIds)
	{
		Debug.Log("AddCardList: " + cardType + " " + cardIds.Count);

		Transform parent = null;
		switch (cardType)
		{
			case ECardType.attack:
				parent = m_View.AttackPanel.transform;
				break;
			case ECardType.defence:
				parent = m_View.DefencePanel.transform;
				break;
			case ECardType.skill:
				parent = m_View.SkillPanel.transform;
				break;
			case ECardType.item:
				parent = m_View.ItemPanel.transform;
				break;
			case ECardType.monster:
			case ECardType.other:
				parent = m_View.EnvPanels.transform;
				break;
			default:
				return;
		}

		for (int i = cardIds.Count - 1; i >= 0; i--)
		{
			string cardId = cardIds[i];
			Card card = CreateCard(cardId);
			UICardSimpleControl cardControl = GetCardSimple(parent);
			cardControl.SetData(card);
			AddBagCard(cardType, cardControl);
		}
	}

	public void AddEnvCardList(List<string> cardIds, int index)
	{
		VerticalLayoutGroup parent = m_EnvPanels[index];

		for (int i = cardIds.Count - 1; i >= 0; i--)
		{
			string cardId = cardIds[i];
			Card card = CreateCard(cardId);
			UICardSimpleControl cardControl = GetCardSimple(parent.transform);
			cardControl.SetData(card, isEnv: true);
			AddEnvCard(index, cardControl);
		}
	}

