	private UICardSimpleControl GetLastBagCard(ECardType cardType)
	{
		List<UICardSimpleControl> cardList = GetBagCardList(cardType);
		if (cardList != null && cardList.Count > 0)
		{
			return cardList[cardList.Count - 1];
